66	    /**
67	     * Resolve the controls that submit with this form, in document order.
68	     * <p>In addition to descendant controls (and controls linked to this form at parse time), this includes controls
69	     * anywhere else in the same Document whose {@code form} attribute references this form's {@code id}, per the
70	     * HTML form-association rules. A control carrying a {@code form} attribute belongs solely to its referenced form:
71	     * a descendant with a {@code form} attribute pointing elsewhere is excluded, and an unresolvable reference (no
72	     * such id, or the target is not a form) associates it with nothing. When several forms share an id, only the
73	     * first such form in document order absorbs externally-associated controls. Computed fresh from the live DOM on
74	     * every call; the form must have a non-empty id to absorb any external controls.</p>
75	     */
76	    private Elements formControls() {
77	        Document doc = ownerDocument();
78	        if (doc == null)
79	            return elements(); // a detached form has no document to resolve external associations against
80	
81	        String id = id();
82	        // Per the HTML spec, a form attribute resolves to the first element in tree order with that id, and only
83	        // associates when that element is a form. So this form absorbs external controls solely when it itself is
84	        // that first element: a missing id, a non-form target, another form, or an earlier same-id form all fail.
85	        boolean absorbsExternals = id.length() > 0 && doc.getElementById(id) == this;
86	
87	        Set<Element> descendants = new HashSet<>(this.getAllElements());
88	        Set<Element> linked = new HashSet<>(linkedEls);
89	        Elements controls = new Elements();
90	        for (Element el : doc.getAllElements()) { // a single document-order pass merges descendants and external controls
91	            if (!el.tag().isFormSubmittable()) continue;
92	            boolean belongs;
93	            if (el.hasAttr("form")) // an explicit association decides, even for descendants (form="" resolves to nothing)
94	                belongs = absorbsExternals && el.attr("form").equals(id);
95	            else
96	                belongs = descendants.contains(el) || linked.contains(el); // implicit: descendant, or linked at parse time
97	            if (belongs) controls.add(el);
98	        }
99	        return controls;
100	    }
