131	    /**
132	     * Get the data that this form submits, using the browser's <i>successful controls</i> semantics: controls are
133	     * returned in DOM order; controls without a {@code name}, disabled controls (including those inside a disabled
134	     * {@code fieldset}, excepting descendants of that fieldset's first {@code legend} child), and {@code button} /
135	     * {@code reset} / {@code submit} / {@code image} inputs are excluded;
136	     * checkboxes and radios are only included when {@code checked} (defaulting to the value {@code "on"}); a
137	     * {@code select[multiple]} submits every selected option, while a single {@code select} with no selected option
138	     * falls back to its first non-disabled option. Options that are disabled, either directly or by a disabled
139	     * {@code optgroup} ancestor, are never submitted.
140	     * <p>In addition to the form's descendant controls, controls elsewhere in the same Document that carry a
141	     * {@code form} attribute whose value is this form's {@code id} are submitted as well (matching the browser's
142	     * <a href="https://html.spec.whatwg.org/multipage/form-control-infrastructure.html#association-of-controls-and-forms">
143	     * form-associated elements</a> rules). All controls are merged in document order. A control with a {@code form}
144	     * attribute is handled solely by that explicit association, even when it is also a descendant: an unresolvable
145	     * value (no such id, the target is not a form, or an earlier form in the Document shares this id) excludes it.
146	     * Forms without an id absorb no external controls.</p>
147	     * The list is re-queried from the DOM on each call, so changes to the document are reflected. The returned list is a copy of the data, and changes to the contents of the
148	     * list will not be reflected in the DOM.
149	     * @return a list of key vals
150	     */
151	    public List<Connection.KeyVal> formData() {
152	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
153	
154	        // iterate the form control elements and accumulate their values
155	        for (Element el: formControls()) {
156	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
157	            if (isDisabled(el)) continue; // skip disabled form inputs
158	            String name = el.attr("name");
159	            if (name.length() == 0) continue;
160	            String type = el.attr("type");
161	
162	            if (el.nameIs("button") || type.equalsIgnoreCase("button") || type.equalsIgnoreCase("reset")
163	                || type.equalsIgnoreCase("submit") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these (a submit button only if it was the clicker)
164	
165	            if (el.nameIs("select")) {
166	                Elements options = el.select("option[selected]");
167	                boolean set = false;
168	                for (Element option: options) {
169	                    if (isDisabledOption(option)) continue; // disabled options are not successful
170	                    data.add(HttpConnection.KeyVal.create(name, option.val()));
171	                    set = true;
172	                }
173	                if (!set && !el.hasAttr("multiple")) {
174	                    // a single select defaults to its first non-disabled option
175	                    for (Element option : el.select("option")) {
176	                        if (!isDisabledOption(option)) {
177	                            data.add(HttpConnection.KeyVal.create(name, option.val()));
178	                            break;
179	                        }
180	                    }
181	                }
182	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
183	                // only add checkbox or radio if they have the checked attribute
184	                if (el.hasAttr("checked")) {
185	                    final String val = el.val().length() >  0 ? el.val() : "on";
186	                    data.add(HttpConnection.KeyVal.create(name, val));
187	                }
188	            } else {
189	                data.add(HttpConnection.KeyVal.create(name, el.val()));
190	            }
191	        }
192	        return data;
193	    }
