200	        if (option.hasAttr("disabled")) return true;
201	        for (Element parent = option.parent(); parent != null && !parent.nameIs("select"); parent = parent.parent()) {
202	            if (parent.nameIs("optgroup") && parent.hasAttr("disabled"))
203	                return true;
204	        }
205	        return false;
206	    }
