210	     * {@code fieldset} that does. Controls descending from the fieldset's first {@code legend} element child are
211	     * excepted from that fieldset's disabling (but may still be disabled by their own attribute or another
212	     * ancestor fieldset). Evaluated from the live DOM on each call.
213	     */
214	    private static boolean isDisabled(Element el) {
215	        if (el.hasAttr("disabled")) return true;
216	        for (Element parent = el.parent(); parent != null; parent = parent.parent()) {
217	            if (parent.nameIs("fieldset") && parent.hasAttr("disabled") && !inFirstLegend(parent, el))
218	                return true;
219	        }
220	        return false;
221	    }
