223	    /**
224	     * Tests if {@code el} descends from the first {@code legend} element child of {@code fieldset} (which must be an
225	     * ancestor of {@code el}). Only that first direct-child legend is excepted; later or nested legends are not.
226	     */
227	    private static boolean inFirstLegend(Element fieldset, Element el) {
228	        Element legend = null;
229	        for (Element child : fieldset.children()) {
230	            if (child.nameIs("legend")) {
231	                legend = child;
232	                break;
233	            }
234	        }
235	        if (legend == null) return false;
236	        for (Element parent = el.parent(); parent != null && parent != fieldset; parent = parent.parent()) {
237	            if (parent == legend) return true;
238	        }
239	        return false;
240	    }
